// ============================================================
// CAN FD Frame Decoder — STM32 Sensor Hub
// Matches can_frames.c
//
// Frame ID map:
//   0x040  — steering              (AS5600 #1)   deg * 10   uint16 BE
//   0x122  — stepper_FeedbackLeft  (AS5600 #2)   deg * 10   uint16 BE
//   0x123  — stepper_FeedbackRight (AS5600 #3)   deg * 10   uint16 BE
//   0x2C8  — throttle_Input        (ADC1)         V * 1000   uint16 BE
//   0x420  — motor_RpmLeft         (Hall #1)      rpm * 10   uint16 BE
//   0x421  — motor_RpmRight        (Hall #2)      rpm * 10   uint16 BE
//   0x480  — motor_VibrationLeft   (ADXL345 #1)  1 byte boolean (0=safe, 1=unsafe)
//   0x481  — motor_VibrationRight  (ADXL345 #2)  1 byte boolean (0=safe, 1=unsafe)
// ============================================================

msg.result = {};

const id   = msg.payload.canid;
const data = msg.payload.data;

// Helper: format raw bytes as hex strings e.g. ["0A", "FF"]
const toHexArray = (arr) => arr.map(b => b.toString(16).toUpperCase().padStart(2, '0'));

// Helper: format CAN ID as fixed-width hex string e.g. 0x040
const toHexId = (id) => "0x" + id.toString(16).toUpperCase().padStart(3, '0');

switch (id) {

    // 0x040 — steering  (AS5600 #1)  @ 500 Hz
    case 0x040:
        const steering_int = (data[0] << 8) | data[1];
        msg.result = {
            frame:   toHexId(id),
            signal:  "steering",
            degrees: steering_int / 10.0,
            raw:     toHexArray([data[0], data[1]])
        };
        break;

    // 0x122 — stepper_FeedbackLeft  (AS5600 #2)  @ 10 Hz
    case 0x122:
        const stepperLeft_int = (data[0] << 8) | data[1];
        msg.result = {
            frame:   toHexId(id),
            signal:  "stepper_FeedbackLeft",
            degrees: stepperLeft_int / 10.0,
            raw:     toHexArray([data[0], data[1]])
        };
        break;

    // 0x123 — stepper_FeedbackRight  (AS5600 #3)  @ 10 Hz
    case 0x123:
        const stepperRight_int = (data[0] << 8) | data[1];
        msg.result = {
            frame:   toHexId(id),
            signal:  "stepper_FeedbackRight",
            degrees: stepperRight_int / 10.0,
            raw:     toHexArray([data[0], data[1]])
        };
        break;

    // 0x2C8 — throttle_Input  (ADC1)  @ 50 Hz
    case 0x2C8:
        const throttle_int = (data[0] << 8) | data[1];
        msg.result = {
            frame:   toHexId(id),
            signal:  "throttle_Input",
            voltage: throttle_int / 1000.0,
            raw:     toHexArray([data[0], data[1]])
        };
        break;

    // 0x420 — motor_RpmLeft  (Hall #1)  @ 1000 Hz
    case 0x420:
        const rpmLeft_int = (data[0] << 8) | data[1];
        msg.result = {
            frame:  toHexId(id),
            signal: "motor_RpmLeft",
            rpm:    rpmLeft_int / 10.0,
            raw:    toHexArray([data[0], data[1]])
        };
        break;

    // 0x421 — motor_RpmRight  (Hall #2)  @ 1000 Hz
    case 0x421:
        const rpmRight_int = (data[0] << 8) | data[1];
        msg.result = {
            frame:  toHexId(id),
            signal: "motor_RpmRight",
            rpm:    rpmRight_int / 10.0,
            raw:    toHexArray([data[0], data[1]])
        };
        break;

    // 0x480 — motor_VibrationLeft  (ADXL345 #1)  @ 100 Hz
    case 0x480:
        msg.result = {
            frame:     toHexId(id),
            signal:    "motor_VibrationLeft",
            is_unsafe: data[0] === 1,
            raw:       toHexArray([data[0]])
        };
        break;

    // 0x481 — motor_VibrationRight  (ADXL345 #2)  @ 100 Hz
    case 0x481:
        msg.result = {
            frame:     toHexId(id),
            signal:    "motor_VibrationRight",
            is_unsafe: data[0] === 1,
            raw:       toHexArray([data[0]])
        };
        break;

    default:
        msg.result = {
            frame:  toHexId(id),
            signal: "unknown",
            raw:    toHexArray(data)
        };
        break;
}

msg.payload = msg.result;
return msg;

// msg.payload is temperature in °C
const t = Number(msg.payload);
msg.payload = t;

// pick your colors
msg.ui_update = msg.ui_update || {};
msg.ui_update.style = msg.ui_update.style || {};

// red if >= 60, otherwise normal
msg.ui_update.style.color = (t >= 60) ? "#ff0000" : "#00bcd4";      // text/needle color
msg.ui_update.style["--gauge-fill"] = (t >= 60) ? "#ff0000" : "#00bcd4"; // some widgets use CSS vars

return msg;

const THRESH = 60;

function randTemp() {
  let t = 20 + Math.random() * 50;  // 20..70
  return Math.round(t * 10) / 10;
}

// Create 6 temps
const temps = Array.from({ length: 6 }, randTemp);

// -------- Output 1: UI update (NO payload!) --------
// Note: when adjusting series settings, include ALL series each time. :contentReference[oaicite:2]{index=2}
const updateMsg = {
  ui_update: {
    chartOptions: {
      series: [
        { name: "Normal", type: "bar", stack: "temps", itemStyle: { color: "#00bcd4" } },
        { name: "Hot", type: "bar", stack: "temps", itemStyle: { color: "red" } }
      ]
    }
  }
};

// -------- Output 2: Data (Replace) --------
const payload = [];

for (let i = 0; i < 6; i++) {
  const label = `Battery ${i + 1}`;
  const t = temps[i];

  payload.push({
    series: "Normal",
    property: label,
    y: (t >= THRESH) ? null : t
  });

  payload.push({
    series: "Hot",
    property: label,
    y: (t >= THRESH) ? t : null
  });
}

const dataMsg = {
  action: "replace",
  payload
};

return [updateMsg, dataMsg];

// Generate smooth-ish random motion (not jumpy)

// store previous values
let roll = context.get("roll") || 0;
let pitch = context.get("pitch") || 0;

// small random changes (like real boat movement)
roll += (Math.random() - 0.5) * 4;   // ±2 deg change
pitch += (Math.random() - 0.5) * 2;  // ±1 deg change

// clamp values to realistic boat limits
roll = Math.max(-45, Math.min(45, roll));
pitch = Math.max(-20, Math.min(20, pitch));

// save back to context
context.set("roll", roll);
context.set("pitch", pitch);

// send to dashboard
msg.payload = {
    roll: roll,
    pitch: pitch
};

return msg;

// Get start time from flow context
let startTime = flow.get("startTime");

// If no start time, initialize it
if (!startTime) {
    startTime = Date.now();
    flow.set("startTime", startTime);
}

// Calculate elapsed time
let elapsedMs = Date.now() - startTime;

// Convert to minutes + hours
let totalMinutes = Math.floor(elapsedMs / 60000);
let hours = Math.floor(totalMinutes / 60);
let minutes = totalMinutes % 60;

// Format output
msg.payload = `${hours} hr ${minutes} min`;

return msg;

// ============================================================
// InfluxDB Mapper — Prep CAN data for Stackhero
// Matches updated CAN decoder signal names
//
// Per-signal DB write rate limits (independent of CAN TX rate):
//   steering              → 20 Hz  (50ms)
//   stepper_FeedbackLeft  → 10 Hz  (100ms)
//   stepper_FeedbackRight → 10 Hz  (100ms)
//   throttle_Input        → 10 Hz  (100ms)
//   motor_RpmLeft         → 10 Hz  (100ms)
//   motor_RpmRight        → 10 Hz  (100ms)
//   motor_VibrationLeft   → 10 Hz  (100ms)
//   motor_VibrationRight  → 10 Hz  (100ms)
// ============================================================

const decoded = msg.payload;

// Don't write unknown frames to the DB
if (decoded.signal === "unknown") {
    return null;
}

// --- Per-signal minimum interval between DB writes (ms) ---
const WRITE_INTERVAL_MS = {
    steering:               50,   // 20 Hz
    stepper_FeedbackLeft:   100,  // 10 Hz
    stepper_FeedbackRight:  100,  // 10 Hz
    throttle_Input:         100,  // 10 Hz
    motor_RpmLeft:          100,  // 10 Hz
    motor_RpmRight:         100,  // 10 Hz
    motor_VibrationLeft:    100,  // 10 Hz
    motor_VibrationRight:   100,  // 10 Hz
};

// --- Throttle check using node context to persist last-write timestamps ---
const now      = Date.now();
const lastKey  = "lastWrite_" + decoded.signal;
const last     = context.get(lastKey) || 0;
const interval = WRITE_INTERVAL_MS[decoded.signal] ?? 100;

if (now - last < interval) {
    return null;
}
context.set(lastKey, now);

// 1. Define the measurement name
const measurementName = "can_sensor_data";

// 2. Prepare fields (the numerical or boolean values to graph)
let fields = {};

if (decoded.degrees !== undefined) {
    fields.value = decoded.degrees;
} else if (decoded.rpm !== undefined) {
    fields.value = decoded.rpm;
} else if (decoded.voltage !== undefined) {
    fields.value = decoded.voltage;
} else if (decoded.is_unsafe !== undefined) {
    // Store as integer 0/1 only — InfluxDB mean() does not support booleans
    fields.value = decoded.is_unsafe ? 1 : 0;
}

// 3. Construct the Stackhero-formatted payload
msg.payload = {
    bucket: "SolarBoatData2025-2026",
    precision: "ms",
    data: {
        measurement: measurementName,
        tags: {
            signal: decoded.signal,  // e.g. "motor_VibrationLeft"
            can_id: decoded.frame    // e.g. "0x480"
        },
        fields: fields,
        timestamp: now
    }
};

return msg;

// Generate a random temperature value for testing
const testValue = Math.floor(Math.random() * (30 - 18 + 1)) + 18;

msg.payload = {
    // The bucket/measurement name
    bucket: "SolarBoatData2025-2026",
    precision: "s", // precision: s, ms, us, ns
    data: {
        measurement: "sensor_test",
        tags: {
            location: "office",
            sensor_id: "DHT22"
        },
        fields: {
            temp: testValue,
            // status: "online"
        },
        timestamp: Math.floor(Date.now() / 1000)
    }
};

return msg;
